S = "Hakeem Force Academy"
QS = [
(S, "Which of the following is the meaning of the word marginal?", ["Of minor or small importance", "Extremely large", "Very famous", "Completely hidden"], 0, "Marginal means small, slight or of minor importance, or relating to an edge or margin. A marginal gain is therefore a very small gain.", "The word comes from the Latin word margo, meaning edge.", [3516]),
(S, "Which word is the antonym (opposite) of marginal in the sense of minor or slight?", ["Significant", "Slight", "Minor", "Narrow"], 0, "Marginal means small or of little importance. The opposite is significant, meaning large or important.", "Marginal can also mean at the edge, and then its opposite is central.", [902]),
(S, "What is a Field Marshal?", ["The highest rank in an army", "A rank just below Major", "A rank in the navy only", "A police officer in charge of a district"], 0, "Field Marshal is the highest (five-star) rank in the army of many countries. It is often given as an honour and is rarely awarded.", "Ayub Khan became the first and only Field Marshal of Pakistan Army in 1959.", [865]),
(S, "On which date was the first martial law imposed in Pakistan?", ["7 October 1958", "5 July 1977", "12 October 1999", "25 March 1969"], 0, "President Iskander Mirza imposed martial law on 7 October 1958 and General Ayub Khan became the Chief Martial Law Administrator. Ayub Khan then removed Mirza on 27 October 1958.", "The second martial law came in 1969 under Yahya Khan and the third in 1977 under Zia-ul-Haq.", [949, 4102]),
(S, "Who was the President of Pakistan when the first martial law was imposed in 1958?", ["Iskander Mirza", "Ayub Khan", "Ghulam Muhammad", "Yahya Khan"], 0, "Iskander Mirza was President and he himself declared martial law on 7 October 1958 by abrogating the 1956 Constitution. Ayub Khan was Army chief and became the Chief Martial Law Administrator.", "Mirza was forced out within three weeks and later went into exile in London.", [5183]),
(S, "How many Muslims were martyred in the Battle of Badr?", ["14", "70", "7", "313"], 0, "Fourteen Muslims were martyred at Badr, of whom six were Muhajireen and eight were Ansar. About 70 Quraish were killed.", "The Muslim army at Badr numbered about 313 men.", [1867]),
(S, "Who gave the atomic theory of matter in the early nineteenth century?", ["John Dalton", "Ernest Rutherford", "Niels Bohr", "J. J. Thomson"], 0, "John Dalton proposed in 1803 that matter is made of tiny indivisible particles called atoms, with atoms of one element being alike. This is called Dalton's atomic theory.", "Rutherford later discovered the nucleus and Bohr gave the planetary model of the atom.", [4850]),
(S, "Who has scored the most Test runs for Pakistan?", ["Younis Khan", "Javed Miandad", "Inzamam-ul-Haq", "Misbah-ul-Haq"], 0, "Younis Khan scored 10,099 runs in Tests and is Pakistan's leading Test run scorer. He was the first Pakistani to pass 10,000 Test runs.", "Javed Miandad (8,832) and Inzamam-ul-Haq (8,829) come next.", [4860]),
(S, "If m = n in a matrix of order m x n, what type of matrix is it?", ["Square matrix", "Row matrix", "Column matrix", "Null matrix"], 0, "A matrix with the same number of rows and columns (m = n) is called a square matrix.", "Only square matrices have a determinant.", [2034]),
(S, "What is the median of 2, 3, 5, 4, 7?", ["4", "5", "3", "4.2"], 0, "Arrange in order: 2, 3, 4, 5, 7. With five values the middle (third) value is 4.", "The mean of these numbers is 4.2, which is different from the median.", [3533]),
(S, "What is the median of 36 and 18?", ["27", "18", "36", "54"], 0, "For two values the median is their average: (18 + 36) / 2 = 54 / 2 = 27.", "For an even number of values the median is the mean of the two middle values.", [992]),
(S, "What is the median of the series 2, 4, 6, 7, 9?", ["6", "4", "7", "5.6"], 0, "The numbers are already in order and there are five of them, so the middle (third) value is 6.", "The mean is 28 / 5 = 5.6, which differs from the median.", [3534]),
(S, "What is the meaning of deceit?", ["Dishonest trickery to mislead someone", "Great sadness", "Sincere honesty", "A kind gift"], 0, "Deceit means the act of deceiving, that is, cheating or misleading someone by dishonest behaviour.", "Its opposite is honesty.", [3502]),
(S, "What is the meaning of disconnect?", ["To break the connection or separate", "To join together", "To repair", "To increase"], 0, "Disconnect means to detach or break the link between two things, for example to cut off a phone line.", "Its opposite is connect.", [3503]),
(S, "What is the meaning of emancipate?", ["To set free", "To imprison", "To punish", "To employ"], 0, "Emancipate means to free someone from legal, social or political restrictions, for example from slavery.", "The Emancipation Proclamation of 1863 declared slaves in the Confederate states free in the USA.", [3505]),
(S, "What is the meaning of mirth?", ["Amusement and laughter", "Anger", "Poverty", "Fear"], 0, "Mirth means joyful amusement, especially when shown by laughter.", "Its synonyms are merriment and gaiety.", [3517]),
(S, "What is the meaning of the word geminate?", ["To double or arrange in pairs", "To destroy", "To hide", "To divide into three"], 0, "Geminate means to double something or to occur in pairs. It comes from the Latin gemini, meaning twins.", "In linguistics a geminate is a doubled consonant sound.", [3510]),
(S, "What does the name Moen jo Daro (Mohenjo-daro) mean?", ["Mound of the dead", "City of kings", "Land of rivers", "Hill of gold"], 0, "Mohenjo-daro is a Sindhi name meaning Mound of the Dead. It was a major city of the Indus Valley Civilization.", "It is located in Larkana district of Sindh and is a UNESCO World Heritage Site.", [2497]),
(S, "What is the meaning of the name Anas?", ["Affection and friendliness", "Sword", "Light", "Lion"], 0, "The Arabic name Anas means affection, friendliness or companionship. Hazrat Anas bin Malik (RA) was a famous servant and companion of the Prophet (PBUH).", "Anas bin Malik narrated over two thousand hadiths.", [3528]),
]
